export const DPIA_HOOK_CONTEXT_BLOCK: string =
"// ── [RATIFY] — the direction matrix (doc 213 §4, amended by doc 222 §3 and\r\n// doc 224), as data — VERBATIM COPY of LIA_HOOK_DIRECTION_MATRIX. See that\r\n// file's own header: this table exists only so a byte-pin test can catch\r\n// drift between the DATA and the CODE (`directionFor`, hook-types.ts, the\r\n// shared, product-agnostic module both products' joins call). ─────────────\r\n\r\nexport interface DpiaHookMatrixRow {\r\n  readonly posture: string;\r\n  readonly fact_agreement: string;\r\n  readonly engine_verdict: string;\r\n  readonly shape: string;\r\n  readonly note: string;\r\n}\r\n\r\nexport const DPIA_HOOK_DIRECTION_MATRIX: readonly DpiaHookMatrixRow[] = [\r\n  {\r\n    posture: \"accepted\",\r\n    fact_agreement: \"same\",\r\n    engine_verdict: \"any\",\r\n    shape: \"S1 supports\",\r\n    note: \"hedged to `likely` language; never lifts a determination\",\r\n  },\r\n  {\r\n    posture: \"accepted\",\r\n    fact_agreement: \"different / unknown\",\r\n    engine_verdict: \"any\",\r\n    shape: \"omit\",\r\n    note: \"nothing to say\",\r\n  },\r\n  {\r\n    posture: \"conditional\",\r\n    fact_agreement: \"same\",\r\n    engine_verdict: \"passes, and every condition_atom holds on the record\",\r\n    shape: \"S5b recognised + condition satisfied\",\r\n    note: \"the engine's pass is what satisfies the condition; the hook only echoes it (doc 222 §3)\",\r\n  },\r\n  {\r\n    posture: \"conditional\",\r\n    fact_agreement: \"same\",\r\n    engine_verdict: \"otherwise (fails / uncertain, or condition_atoms null / not all held)\",\r\n    shape: \"S5a recognised, condition unresolved\",\r\n    note: \"the guidance is relevant; whether its condition is met is Section {section}'s question — never asserted here (the doc 218 D1 defect)\",\r\n  },\r\n  {\r\n    posture: \"conditional\",\r\n    fact_agreement: \"different (a distinguishing pair holds)\",\r\n    engine_verdict: \"passes\",\r\n    shape: \"omit + assessor flag `authority_not_dispositive` (`rule_missing` when the pair expressly excludes)\",\r\n    note: \"a silent source under a pass is nothing missing; an express exclusion under a pass is the lawyer's rule\",\r\n  },\r\n  {\r\n    posture: \"conditional\",\r\n    fact_agreement: \"different (a distinguishing pair holds)\",\r\n    engine_verdict: \"fails / uncertain\",\r\n    shape: \"S6 source silent (S6x where the pair expressly excludes)\",\r\n    note: \"\\\"does not extend\\\" only from an authored `source_expressly_excludes` pair with a verified exclusion span (doc 222 §2.4)\",\r\n  },\r\n  {\r\n    posture: \"conditional\",\r\n    fact_agreement: \"unknown\",\r\n    engine_verdict: \"any\",\r\n    shape: \"omit\",\r\n    note: \"\",\r\n  },\r\n  {\r\n    posture: \"rejected\",\r\n    fact_agreement: \"same\",\r\n    engine_verdict: \"fails / uncertain\",\r\n    shape: \"S2 cuts against and applied\",\r\n    note: \"the determination already reflects it\",\r\n  },\r\n  {\r\n    posture: \"rejected\",\r\n    fact_agreement: \"same\",\r\n    engine_verdict: \"passes\",\r\n    shape: \"omit + assessor flag `rule_missing`\",\r\n    note:\r\n      \"the lawyer's rule: an adverse authority on the same facts under a pass means a rule is missing — never printed as \\\"risk noted\\\"\",\r\n  },\r\n  {\r\n    posture: \"rejected\",\r\n    fact_agreement: \"different (a distinguishing pair holds)\",\r\n    engine_verdict: \"any\",\r\n    shape: \"S3 cuts against but distinguished\",\r\n    note: \"renders only from the pair (source fact / record fact); never from an atom's generic phrase\",\r\n  },\r\n  {\r\n    posture: \"rejected\",\r\n    fact_agreement: \"unknown\",\r\n    engine_verdict: \"any\",\r\n    shape: \"omit\",\r\n    note: \"\",\r\n  },\r\n  {\r\n    posture: \"contested (R4)\",\r\n    fact_agreement: \"same\",\r\n    engine_verdict: \"any\",\r\n    shape: \"S4 noted as a boundary\",\r\n    note: \"prints the derived status and the appeal note; no relation drawn\",\r\n  },\r\n  {\r\n    posture: \"contested (R4)\",\r\n    fact_agreement: \"different / unknown\",\r\n    engine_verdict: \"any\",\r\n    shape: \"omit\",\r\n    note: \"a contested decision on different facts adds nothing (doc 222 §3)\",\r\n  },\r\n  {\r\n    posture: \"any\",\r\n    fact_agreement: \"unknown from atoms\",\r\n    engine_verdict: \"—\",\r\n    shape: \"the stored two-leg selection's agreement, if one exists; else omit + flag `selection_pending`; legs disagreed → omit + flag `selection_unsettled` (the ROO item)\",\r\n    note: \"doc 224 §1: a call is made only where no stored decision exists AND the pre-filter says either answer could print\",\r\n  },\r\n  {\r\n    posture: \"any\",\r\n    fact_agreement: \"`required_atoms` not all held\",\r\n    engine_verdict: \"—\",\r\n    shape: \"not nominated\",\r\n    note: \"\",\r\n  },\r\n];\r\n\r\n// ── [RATIFY — DRAFT, unratified] — the atom-phrase map (doc 213 §5 pattern;\r\n// this build's own DPIA vocabulary, doc 232). One ratified clause per\r\n// closed-list atom value in HOOK_PRODUCT_REGISTRY.dpia\r\n// (generate-corpus-hooks/_local/product-registry.ts). ──────────────────────\r\n\r\nexport const DPIA_ATOM_PHRASES: Readonly<Record<string, string>> = {\r\n  // — classes —\r\n  \"class:employee_monitoring\": \"the processing monitors employees\",\r\n  \"class:public_space_surveillance\": \"the processing systematically monitors a publicly accessible area\",\r\n  \"class:algorithmic_decision\": \"the processing includes automated evaluation, scoring, or decision-making\",\r\n  \"class:innovative_technology_use\": \"the processing uses a novel or innovative technology\",\r\n  \"class:dataset_matching\": \"the processing matches or combines datasets\",\r\n\r\n  // — flags —\r\n  \"flag:biometric\": \"the processing includes biometric data\",\r\n  \"flag:special_category\": \"the processing includes special-category data\",\r\n  \"flag:children\": \"children are among the people affected\",\r\n  \"flag:large_scale\": \"the processing is carried out on a large scale\",\r\n  \"flag:vulnerable_subjects\": \"the processing concerns vulnerable data subjects\",\r\n  \"flag:automated_decision\": \"the processing involves automated decision-making\",\r\n  \"flag:cross_border_transfer\": \"the processing involves a cross-border transfer of personal data\",\r\n\r\n  // — relationships —\r\n  \"relationship:employee\": \"the people affected are employees of the controller\",\r\n  \"relationship:customer\": \"the people affected are customers of the controller\",\r\n  \"relationship:public\": \"the people affected are members of the public with no relationship to the controller\",\r\n\r\n  // — data categories (DPIA_DATA_CATEGORIES / DATA_CATS, DPIAFramework.enums.ts) —\r\n  \"data_category:Contact details\": \"the processing includes contact details\",\r\n  \"data_category:Employee records\": \"the processing includes employee records\",\r\n  \"data_category:Customer records\": \"the processing includes customer records\",\r\n  \"data_category:Health or medical data\": \"the processing includes health or medical data\",\r\n  \"data_category:Financial data\": \"the processing includes financial data\",\r\n  \"data_category:Biometric data\": \"the processing includes biometric data\",\r\n  \"data_category:Children's data\": \"the processing includes children's data\",\r\n  \"data_category:Location data\": \"the processing includes location data\",\r\n  \"data_category:Communications content\": \"the processing includes communications content\",\r\n  \"data_category:Other\": \"the processing includes other categories of data not separately listed\",\r\n\r\n  // — instruments —\r\n  \"instrument:EU GDPR\": \"the processing is assessed under the EU GDPR\",\r\n  \"instrument:UK GDPR\": \"the processing is assessed under the UK GDPR\",\r\n\r\n  // — state: atoms — the closed `reasons_to_conduct` vocabulary (17 options,\r\n  // REASONS_TO_CONDUCT / DPIAFramework.enums.ts), true and false phrasing for\r\n  // each (the `false` form is the only way to phrase an ABSENCE — the doc 223\r\n  // defect this build designs out from day one: a hook may distinguish on a\r\n  // record that DID NOT select a reason only through this explicit `=false`\r\n  // phrase, never by reusing the `=true` phrase for an absent-polarity pair).\r\n  \"state:intake.reasons_to_conduct.art35_3a_evaluation_profiling=true\":\r\n    \"the record selects systematic, extensive evaluation or profiling with significant effects as a reason the assessment was undertaken\",\r\n  \"state:intake.reasons_to_conduct.art35_3a_evaluation_profiling=false\":\r\n    \"the record does not select systematic, extensive evaluation or profiling with significant effects as a reason the assessment was undertaken\",\r\n  \"state:intake.reasons_to_conduct.art35_3b_large_scale_special_category=true\":\r\n    \"the record selects large-scale special-category or criminal-offence data as a reason the assessment was undertaken\",\r\n  \"state:intake.reasons_to_conduct.art35_3b_large_scale_special_category=false\":\r\n    \"the record does not select large-scale special-category or criminal-offence data as a reason the assessment was undertaken\",\r\n  \"state:intake.reasons_to_conduct.art35_3c_public_area_monitoring=true\":\r\n    \"the record selects large-scale systematic monitoring of a public area as a reason the assessment was undertaken\",\r\n  \"state:intake.reasons_to_conduct.art35_3c_public_area_monitoring=false\":\r\n    \"the record does not select large-scale systematic monitoring of a public area as a reason the assessment was undertaken\",\r\n  \"state:intake.reasons_to_conduct.evaluation_scoring=true\":\r\n    \"the record selects evaluation or scoring, including profiling or prediction, as a reason the assessment was undertaken\",\r\n  \"state:intake.reasons_to_conduct.evaluation_scoring=false\":\r\n    \"the record does not select evaluation or scoring as a reason the assessment was undertaken\",\r\n  \"state:intake.reasons_to_conduct.automated_decision_making=true\":\r\n    \"the record selects automated decision-making with a legal or significant effect as a reason the assessment was undertaken\",\r\n  \"state:intake.reasons_to_conduct.automated_decision_making=false\":\r\n    \"the record does not select automated decision-making with a legal or significant effect as a reason the assessment was undertaken\",\r\n  \"state:intake.reasons_to_conduct.systematic_monitoring=true\":\r\n    \"the record selects systematic monitoring of employees, a defined population, or a non-public space as a reason the assessment was undertaken\",\r\n  \"state:intake.reasons_to_conduct.systematic_monitoring=false\":\r\n    \"the record does not select systematic monitoring of employees, a defined population, or a non-public space as a reason the assessment was undertaken\",\r\n  \"state:intake.reasons_to_conduct.sensitive_data=true\":\r\n    \"the record selects sensitive or highly personal data as a reason the assessment was undertaken\",\r\n  \"state:intake.reasons_to_conduct.sensitive_data=false\":\r\n    \"the record does not select sensitive or highly personal data as a reason the assessment was undertaken\",\r\n  \"state:intake.reasons_to_conduct.large_scale=true\":\r\n    \"the record selects data processed on a large scale as a reason the assessment was undertaken\",\r\n  \"state:intake.reasons_to_conduct.large_scale=false\":\r\n    \"the record does not select data processed on a large scale as a reason the assessment was undertaken\",\r\n  \"state:intake.reasons_to_conduct.matching_combining_datasets=true\":\r\n    \"the record selects matching or combining datasets as a reason the assessment was undertaken\",\r\n  \"state:intake.reasons_to_conduct.matching_combining_datasets=false\":\r\n    \"the record does not select matching or combining datasets as a reason the assessment was undertaken\",\r\n  \"state:intake.reasons_to_conduct.vulnerable_subjects=true\":\r\n    \"the record selects data concerning vulnerable subjects as a reason the assessment was undertaken\",\r\n  \"state:intake.reasons_to_conduct.vulnerable_subjects=false\":\r\n    \"the record does not select data concerning vulnerable subjects as a reason the assessment was undertaken\",\r\n  \"state:intake.reasons_to_conduct.innovative_technology=true\":\r\n    \"the record selects innovative use of new technology as a reason the assessment was undertaken\",\r\n  \"state:intake.reasons_to_conduct.innovative_technology=false\":\r\n    \"the record does not select innovative use of new technology as a reason the assessment was undertaken\",\r\n  \"state:intake.reasons_to_conduct.prevents_exercising_right=true\":\r\n    \"the record selects that the processing prevents exercising a right or using a service as a reason the assessment was undertaken\",\r\n  \"state:intake.reasons_to_conduct.prevents_exercising_right=false\":\r\n    \"the record does not select that the processing prevents exercising a right or using a service as a reason the assessment was undertaken\",\r\n  \"state:intake.reasons_to_conduct.required_by_national_law=true\":\r\n    \"the record selects that the assessment is required by national law\",\r\n  \"state:intake.reasons_to_conduct.required_by_national_law=false\":\r\n    \"the record does not select that the assessment is required by national law\",\r\n  \"state:intake.reasons_to_conduct.dpo_or_data_subject_recommendation=true\":\r\n    \"the record selects a DPO or data-subject recommendation as a reason the assessment was undertaken\",\r\n  \"state:intake.reasons_to_conduct.dpo_or_data_subject_recommendation=false\":\r\n    \"the record does not select a DPO or data-subject recommendation as a reason the assessment was undertaken\",\r\n  \"state:intake.reasons_to_conduct.required_by_code_of_conduct=true\":\r\n    \"the record selects that the assessment is required by a code of conduct or standard\",\r\n  \"state:intake.reasons_to_conduct.required_by_code_of_conduct=false\":\r\n    \"the record does not select that the assessment is required by a code of conduct or standard\",\r\n  \"state:intake.reasons_to_conduct.risk_management_accountability=true\":\r\n    \"the record selects risk management or accountability as a (beneficial, non-mandatory) reason the assessment was undertaken\",\r\n  \"state:intake.reasons_to_conduct.risk_management_accountability=false\":\r\n    \"the record does not select risk management or accountability as a reason the assessment was undertaken\",\r\n  \"state:intake.reasons_to_conduct.existing_processing_risk_changed=true\":\r\n    \"the record selects that this is existing processing whose risk has changed as a reason the assessment was undertaken\",\r\n  \"state:intake.reasons_to_conduct.existing_processing_risk_changed=false\":\r\n    \"the record does not select that this is existing processing whose risk has changed as a reason the assessment was undertaken\",\r\n};\r\n\r\n// ── [RATIFY — DRAFT, unratified] — the sentence shapes (doc 213 §5 pattern\r\n// as amended by doc 222 §4), DPIA-specific text. Slot NAMES are identical to\r\n// LIA's shapes (dpia-hook-join.ts's renderer needs no product-specific\r\n// branching); the WORDING differs where LIA's is legitimate-interest-\r\n// specific (doc 232 build brief: \"S5a/S5b/S6/S6x wording is LIA-specific …\r\n// draft DPIA-appropriate shape text\"). ─────────────────────────────────────\r\n\r\n// DOC 238 (2026-09-09) — AMENDED, still [RATIFY — DRAFT, unratified]: doc 237\r\n// §5 found no current shape, in any product, can produce any CEO-approved\r\n// hook sentence (docs 223B/233/234/236). This revision (a) restructures\r\n// every shape from a 2–4-sentence clause template into the approved\r\n// 4–7-sentence paragraph form, (b) adds the `{quote}` slot (the verified\r\n// `finding_span`, wrapped in quotation marks by the template — quote marks\r\n// are ratified template text, never drafted content, so no verify.ts change\r\n// is needed), (c) adds the optional `{governing_provision}` slot to S1–S4\r\n// (S5a/S5b/S6/S6x already carry an equivalent rule statement via\r\n// `{proposition}`/`{condition}`), and (d) rewords S2/S6x's section pointer\r\n// from backward-asserting (\"…and the determination in Section {section}\r\n// reflects it\") to forward-looking (\"Whether that holds… is addressed in\r\n// Section {section}\") — matching every approved DPIA candidate this session\r\n// (233 §\"AENA\": \"Section 3 addresses whether that analysis is present\";\r\n// §\"ICS\": \"Section 1 records whether that trigger is satisfied\"). S1 is left\r\n// backward-asserting on purpose (doc 233's WP248 candidate: \"supports the\r\n// assessment's position… Section 1 records that determination\" — a\r\n// SUPPORTING finding is properly asserted, not hedged as pending). The hedge\r\n// itself is NOT template text — it is the hook's own CEO-approved\r\n// `hedge_sentence` (hook-types.ts), appended verbatim by the join's\r\n// `hedgeSuffix` after the citation; no generic hedge constant exists (doc\r\n// 238 follow-up, 2026-09-09). See doc 238 §\"DPIA\" for the full proposal, a\r\n// rendered example, and the CEO ratify/revise/hold line.\r\n\r\nexport const DPIA_HOOK_SHAPES: Readonly<Record<\"S1\" | \"S2\" | \"S3\" | \"S4\" | \"S5a\" | \"S5b\" | \"S6\" | \"S6x\", string>> = {\r\n  S1:\r\n    \"The record identifies that {customer_fact}. In {authority}, {regulator} {verb} that where {fact_pattern}, {finding} — in its own words, \\\"{quote}\\\". That finding supports the assessment's position on {factor}. {hedge}Section {section} records that determination. ({citation}; {status}.)\",\r\n  S2:\r\n    \"The record identifies that {customer_fact}. In {authority}, {regulator} found that where {fact_pattern}, {finding} — in its own words, \\\"{quote}\\\". That finding cuts against the assessment's position on {factor}. {hedge}Whether that holds on this record is addressed in Section {section}. ({citation}; {status}.)\",\r\n  S3:\r\n    \"In {authority}, {regulator} found that where {fact_pattern}, {finding} — in its own words, \\\"{quote}\\\". That finding turned on the fact that {source_fact}; on this record the assessment has instead identified {record_fact}. The decision marks a boundary rather than a finding against the record. ({citation}; {status}.)\",\r\n  S4:\r\n    \"In {authority}, {regulator} found that where {fact_pattern}, {finding} — in its own words, \\\"{quote}\\\". The record identifies {customer_fact}. That decision is {status}; it is noted as a boundary and is not applied. ({citation}.)\",\r\n  S5a:\r\n    \"In {authority}, {regulator} {verb} that {proposition} — in its own words, \\\"{quote}\\\" — subject to {condition}. That guidance is relevant to {factor}; whether its condition is satisfied is addressed in Section {section}. ({citation}; {status}.)\",\r\n  S5b:\r\n    \"In {authority}, {regulator} {verb} that {proposition} — in its own words, \\\"{quote}\\\" — subject to {condition}. That guidance is relevant to {factor}; whether its condition is satisfied is addressed in Section {section}. The facts identified in Section {section} satisfy that stated condition. ({citation}; {status}.)\",\r\n  S6:\r\n    \"The record identifies {record_fact}. In {authority}, {regulator} {verb} that {proposition} — in its own words, \\\"{quote}\\\" — subject to {condition}, but does not address whether the same conclusion follows where {record_fact}. The determination in Section {section} therefore rests on the separately identified rules and facts, not on that guidance. ({citation}; {status}.)\",\r\n  S6x:\r\n    \"The record identifies {record_fact}. In {authority}, {regulator} {verb} that {proposition} — in its own words, \\\"{quote}\\\" — subject to {condition}, and that {exclusion_paraphrase}; that exclusion applies to processing of the kind the record describes. Whether it applies here is addressed on {factor} in Section {section}. ({citation}; {status}.)\",\r\n};\r\n\r\n// ── [RATIFY — DRAFT, unratified] — concept equivalence (doc 222 §2.3\r\n// pattern). Two atoms naming the same underlying fact share a concept; the\r\n// render dedupes `{customer_fact}` by concept. ────────────────────────────\r\n\r\nexport const DPIA_ATOM_CONCEPTS: Readonly<Record<string, string>> = {\r\n  \"flag:special_category\": \"special_category\",\r\n  \"data_category:Health or medical data\": \"special_category\",\r\n  \"state:intake.reasons_to_conduct.art35_3b_large_scale_special_category=true\": \"special_category\",\r\n  \"flag:children\": \"children\",\r\n  \"data_category:Children's data\": \"children\",\r\n  \"state:intake.reasons_to_conduct.vulnerable_subjects=true\": \"vulnerable_subjects\",\r\n  \"flag:vulnerable_subjects\": \"vulnerable_subjects\",\r\n  \"flag:biometric\": \"biometric\",\r\n  \"data_category:Biometric data\": \"biometric\",\r\n  \"flag:large_scale\": \"large_scale\",\r\n  \"state:intake.reasons_to_conduct.large_scale=true\": \"large_scale\",\r\n  \"flag:automated_decision\": \"automated_decision\",\r\n  \"class:algorithmic_decision\": \"automated_decision\",\r\n  \"state:intake.reasons_to_conduct.automated_decision_making=true\": \"automated_decision\",\r\n  \"class:employee_monitoring\": \"employee_monitoring\",\r\n  \"state:intake.reasons_to_conduct.systematic_monitoring=true\": \"employee_monitoring\",\r\n};\r\n\r\n/** The concept an atom names — itself when the table has no entry. */\r\nexport function dpiaAtomConcept(atom: string): string {\r\n  return DPIA_ATOM_CONCEPTS[atom] ?? atom;\r\n}\r\n\r\n// ── [RATIFY — DRAFT, unratified] — factor phrases (doc 222 §5 pattern): the\r\n// `{factor}` slot, without a leading article. Every factor maps to exactly\r\n// one of DPIA's two hook elements (`DPIA_FACTOR_ELEMENT`, below) — doc 232's\r\n// factor/determination → section map. ──────────────────────────────────────\r\n\r\nconst F_OBLIGATION = \"the Article 35 obligation to conduct this assessment\";\r\nconst F_EMPLOYEE_MONITORING = \"the employee-monitoring trigger\";\r\nconst F_ALGORITHMIC = \"the automated-decision trigger\";\r\nconst F_ADEQUACY = \"the necessity and proportionality analysis\";\r\nconst F_BIOMETRIC_ADEQUACY = \"the adequacy of the biometric-processing analysis\";\r\n// doc 242, three-lawyer panel (2026-09-09): both live profile factor_ids\r\n// verbatim, already following the \"the [X] trigger\" naming convention.\r\nconst F_CHILDRENS_DATA = \"the children's-data trigger\";\r\nconst F_INNOVATIVE_TECH = \"the innovative-technology trigger\";\r\n\r\nexport const DPIA_FACTOR_PHRASES: Readonly<Record<string, string>> = {\r\n  [F_OBLIGATION]: \"the obligation to conduct this assessment\",\r\n  [F_EMPLOYEE_MONITORING]: \"the employee-monitoring trigger\",\r\n  [F_ALGORITHMIC]: \"the automated-decision trigger\",\r\n  [F_ADEQUACY]: \"necessity and proportionality\",\r\n  [F_BIOMETRIC_ADEQUACY]: \"the adequacy of the biometric-processing analysis\",\r\n  // doc 242, three-lawyer panel (2026-09-09): both are Article 35(1)\r\n  // trigger factors (WP248 criteria 7/8), the same kind of question as\r\n  // employee-monitoring/automated-decision above — obligation, not\r\n  // adequacy.\r\n  [F_CHILDRENS_DATA]: \"the children's-data trigger\",\r\n  [F_INNOVATIVE_TECH]: \"the innovative-technology trigger\",\r\n};\r\n\r\n// ── [RATIFY — DRAFT, unratified] — DOC 213 §2 pattern: factor → DPIA hook\r\n// element (\"obligation\" | \"adequacy\" — dpia-hook-join.ts's\r\n// `SECTION_FOR_ELEMENT`/`bears_on_element`). Copied verbatim into\r\n// generate-corpus-hooks/_local/dpia-factor-element.ts (pinned by test), the\r\n// same relationship LIA_FACTOR_ELEMENT has to\r\n// generate-corpus-hooks/_local/factor-element.ts. ──────────────────────────\r\n\r\nexport const DPIA_FACTOR_ELEMENT: Readonly<Record<string, \"obligation\" | \"adequacy\">> = {\r\n  [F_OBLIGATION]: \"obligation\",\r\n  [F_EMPLOYEE_MONITORING]: \"obligation\",\r\n  [F_ALGORITHMIC]: \"obligation\",\r\n  [F_ADEQUACY]: \"adequacy\",\r\n  [F_BIOMETRIC_ADEQUACY]: \"adequacy\",\r\n  [F_CHILDRENS_DATA]: \"obligation\",\r\n  [F_INNOVATIVE_TECH]: \"obligation\",\r\n};\r\n\r\nexport function dpiaElementOf(factorId: string): \"obligation\" | \"adequacy\" | null {\r\n  return DPIA_FACTOR_ELEMENT[factorId] ?? null;\r\n}\r\n\r\n// ── [RATIFY] — source status labels (doc 222 §2.7) — VERBATIM COPY of\r\n// LIA_SOURCE_STATUS_LABELS. Product-agnostic: HookSourceStatus\r\n// (hook-types.ts) carries no LIA-specific vocabulary. ──────────────────────\r\n\r\nexport const DPIA_SOURCE_STATUS_LABELS: Readonly<Record<string, string>> = {\r\n  edpb_guidelines_final: \"EDPB guidelines — interpretive guidance, not binding law\",\r\n  edpb_opinion: \"EDPB Article 64 opinion — Board opinion, not a judicial decision\",\r\n  wp29_opinion: \"Article 29 Working Party opinion — historical interpretive guidance\",\r\n  regulator_guidance: \"regulatory guidance — non-binding\",\r\n  sa_decision: \"supervisory-authority decision — persuasive, non-binding outside its jurisdiction\",\r\n  sa_decision_affirmed: \"supervisory-authority decision, affirmed on appeal\",\r\n  sa_decision_appeal_pending: \"under appeal\",\r\n};\r\n\r\n// ── RATIFIED (LIA, CEO 2026-09-08) — BYTE-MIRRORED here, unchanged. Where an\r\n// appeal is known to have been made, the join appends this sentence,\r\n// verbatim, after the hook's sentence. ─────────────────────────────────────\r\n\r\nexport const DPIA_APPEAL_SENTENCE = \"This matter is subject to an appeal which could invalidate this ruling.\";\r\n\r\nexport const DPIA_SETTLEDNESS_LABELS: Readonly<Record<\"R1\" | \"R2\" | \"R3\" | \"R4\", string>> = {\r\n  R1: \"adopted guidance or settled authority\",\r\n  R2: \"a settled line of decisions\",\r\n  R3: \"a single supervisory authority's decision\",\r\n  R4: \"under appeal / contested\",\r\n};\r\n";
